  var tab=BuiltInRegistries.CREATIVE_MODE_TAB.get(id("vandorlabs"));tab.buildContents(new CreativeModeTab.ItemDisplayParameters(level.enabledFeatures(),false,level.registryAccess()));for(int i=0;i<3;i++){final int index=i;need(tab.getDisplayItems().stream().anyMatch(stack->stack.is(item(index)))==(i==0),"only public canonical item in actual creative catalog "+IDS[i]);}
