 private static void mining(){for(int i=0;i<3;i++)for(int half=0;half<2;half++)for(Item tool:new Item[]{Items.STONE_PICKAXE,Items.WOODEN_PICKAXE,Items.AIR}){var pos=BASE.east(i*7);var tile=place(i,pos);var pick=block(i).getCloneItemStack(level.getBlockState(pos.above()),body(tile),level,pos.above(),actor);need(pick.is(item(0))&&pick.getOrDefault(DataComponents.CUSTOM_DATA,CustomData.EMPTY).copyTag().contains("SpaceDoorSettings"),"alias upper pick returns configured canonical item");var tag=tile.saveWithoutMetadata(level.registryAccess());var reader=new CompoundTag();reader.put("InsertedToken",NativeCredentialItems.writeStack(NativeCredentialItems.accessCard(2),level.registryAccess()));tag.put("DoorKeyReader",reader);tile.loadWithComponents(tag,level.registryAccess());actor.setItemInHand(InteractionHand.MAIN_HAND,tool==Items.AIR?ItemStack.EMPTY:new ItemStack(tool));tracked=pos;drops.clear();need(actor.gameMode.destroyBlock(half==0?pos:pos.above()),"actual registered survival mining "+IDS[i]+" half="+half);need(level.getBlockState(pos).isAir()&&level.getBlockState(pos.above()).isAir()&&dropped(item(0))==(tool==Items.STONE_PICKAXE?1:0)&&dropped(NativeCredentialItems.ACCESS_CARD.get())==1,"real harvest/canonical-drop/physical-reader ownership "+IDS[i]+" half="+half+" tool="+tool+" drops="+drops);tracked=null;}}
 private static void collisions(){var tile=place(1,BASE.south(8));edit(tile,0,0,2,false);var pos=tile.getBlockPos();boolean tested=false;for(Direction face:Direction.Plane.HORIZONTAL)for(var hinge:DoorHingeSide.values())if(!tested){for(var cell:new BlockPos[]{pos,pos.above()})level.setBlock(cell,level.getBlockState(cell).setValue(NativeProgrammableDoorBlock.FACING,face).setValue(NativeProgrammableDoorBlock.HINGE,hinge).setValue(NativeProgrammableDoorBlock.OPEN,true),2);var box=level.getBlockState(pos).getCollisionShape(level,pos).bounds();double minX=box.minX,maxX=box.maxX,minZ=box.minZ,maxZ=box.maxZ;if(minX<0)maxX=Math.min(0,maxX);else if(maxX>1)minX=Math.max(1,minX);else if(minZ<0)maxZ=Math.min(0,maxZ);else if(maxZ>1)minZ=Math.max(1,minZ);else continue;if(maxX-minX<1e-4||maxZ-minZ<1e-4)continue;for(int half=0;half<2;half++){var cell=half==0?pos:pos.above();var query=new AABB(cell.getX()+minX+.00001,cell.getY()+.2,cell.getZ()+minZ+.00001,cell.getX()+maxX-.00001,cell.getY()+.8,cell.getZ()+maxZ-.00001);need(!new AABB(cell).intersects(query),"engine collision query wholly outside owner voxel");var found=level.getBlockCollisions(null,query).iterator();need(found.hasNext()&&found.next().bounds().intersects(query),"actual Level.getBlockCollisions finds rotating OPEN overhang half="+half);}tested=true;}need(tested,"actual rotating pose has measurable overhang");level.removeBlock(pos,false);}
