  if(stage==3&&age>=20){need(actor.getInventory().countItem(NativeCredentialItems.ACCESS_CARD.get())==1&&!runtime.readerProjection().front().visual().occupied()&&runtime.securityOpen(),"actual pulse remains open after physical item returned");stage=4;}
